  const now = () => new Date().toISOString();
  const clone = (o) => JSON.parse(JSON.stringify(o));

  // ---------- Carga inicial: desloca todas as datas para "hoje" ----------
  function shifted(data) {
    const delta = Date.now() - new Date(data.exported_at).getTime();
    const walk = (v) => {
      if (Array.isArray(v)) return v.map(walk);
      if (v && typeof v === 'object') { const o = {}; for (const k of Object.keys(v)) o[k] = walk(v[k]); return o; }
      if (typeof v === 'string') {
        if (ISO.test(v)) return new Date(new Date(v).getTime() + delta).toISOString();
        if (DAY.test(v)) return new Date(new Date(v + 'T12:00:00').getTime() + delta).toISOString().slice(0, 10);
      }
      return v;
    };
    const d = walk(data); d.exported_at = now(); return d;
  }
  let db;
  try { db = JSON.parse(localStorage.getItem(KEY)); } catch (_) { db = null; }
  if (!db || db.version !== 1) { db = shifted(window.DEMO_DATA); db.version = 1; db.whatsapp_messages = []; db.attachments = []; db.audit = db.audit || []; }
  const save = () => { try { localStorage.setItem(KEY, JSON.stringify(db)); } catch (_) { /* sem espaço: segue em memória */ } };
  const nextId = (arr) => arr.reduce((m, x) => Math.max(m, Number(x.id) || 0), 0) + 1;
