  const need = () => { if (!user()) fail(401, 'Faça login para continuar.'); return user(); };
  const requireRole = (...roles) => { const u = need(); if (!roles.includes(u.role)) fail(403, 'Você não tem permissão para esta ação.'); return u; };
  const audit = (action, entity, id, details = {}) => { db.audit.unshift({ id: nextId(db.audit), user_id: user() ? user().id : null, user_name: user() ? user().name : null, action, entity, entity_id: id == null ? null : String(id), details, ip: '127.0.0.1', created_at: now() }); db.audit = db.audit.slice(0, 300); };
  const notify = (uid, title, body, link) => { if (!uid) return; db.notifications.unshift({ id: nextId(db.notifications), user_id: uid, title, body: body || null, link: link || null, read_at: null, created_at: now() }); if (user() && uid === user().id) UI.toast(`${title}${body ? ': ' + body : ''}`, 'info', 6000); };
  const byId = (arr, id) => arr.find((x) => x.id === Number(id));
