  const scopeC = (c) => isMgr() || c.owner_id === user().id || c.owner_id == null || db.tickets.some((t) => t.customer_id === c.id && t.assignee_id === user().id);
  const loadC = (id) => { const c = byId(db.customers, id); if (!c || !scopeC(c)) fail(404, 'Cliente não encontrado ou fora do seu escopo.'); return c; };
