    const t = { queue: T.filter((x) => x.status === 'aguardando' && !x.assignee_id).length, unanswered: T.filter((x) => x.awaiting_reply).length, overdue: T.filter((x) => x.awaiting_reply && new Date(x.response_due_at) < Date.now()).length,
      follow_up_overdue: T.filter((x) => x.follow_up_at && new Date(x.follow_up_at) < Date.now() && OPEN.includes(x.status)).length, open: T.filter((x) => OPEN.includes(x.status)).length,
      mine_open: T.filter((x) => x.assignee_id === me && OPEN.includes(x.status)).length, mine_unanswered: T.filter((x) => x.assignee_id === me && x.awaiting_reply).length,
      resolved_today: T.filter((x) => x.status === 'resolvido' && isToday(x.closed_at) && (mgr || x.assignee_id === me)).length, opened_today: T.filter((x) => isToday(x.opened_at)).length,
      fr_samples: fr.length, fr_within_sla: fr.filter((x) => new Date(x.first_response_at) - new Date(x.opened_at) <= s.response_sla_minutes * 60000).length,
      avg_first_response_s: fr.length ? fr.reduce((a, x) => a + (new Date(x.first_response_at) - new Date(x.opened_at)) / 1000, 0) / fr.length : null, sla_minutes: s.response_sla_minutes };
